options.helpers:
var FPGA_PORTS = {'100ge1/0/9':1,'100ge1/0/10':1,'100ge1/0/11':1,'100ge1/0/12':1,'100ge1/0/15':1};
context.handlebars.registerHelper('findPort', function(rows, iface) {
  if (!Array.isArray(rows)) return null;
  return rows.find(function(r) { return r && r.port === iface; }) || null;
});
context.handlebars.registerHelper('dotColor', function(rows, iface) {
  var r = context.handlebars.helpers.findPort(rows, iface);
  if (!r) return '#555';
  if ((+r.Value) > 0) return '#37872d';
  return FPGA_PORTS[iface] ? '#dfa817' : '#8a1a1a';
});
context.handlebars.registerHelper('portFill', function(rows, iface) {
  var r = context.handlebars.helpers.findPort(rows, iface);
  if (!r) return '#242830';
  if ((+r.Value) > 0) return '#1e3a20';
  return FPGA_PORTS[iface] ? '#3d2f10' : '#3a1a1a';
});
context.handlebars.registerHelper('arrowFor', function(rows, iface) {
  var r = context.handlebars.helpers.findPort(rows, iface);
  if (!r) return 'aDn';
  if ((+r.Value) > 0) return 'aUp';
  return FPGA_PORTS[iface] ? 'aIdle' : 'aDn';
});
